drop policy if exists "qr_codes_member_all" on public.qr_codes; create policy "qr_codes_member_advanced_all" on public.qr_codes for all to authenticated using (exists(select 1 from public.locations l join public.business_members bm on bm.business_id=l.business_id join public.businesses b on b.id=l.business_id where l.id=qr_codes.location_id and bm.user_id=auth.uid() and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier)) with check (exists(select 1 from public.locations l join public.business_members bm on bm.business_id=l.business_id join public.businesses b on b.id=l.business_id where l.id=qr_codes.location_id and bm.user_id=auth.uid() and bm.role=any(array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier));
